sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }


    var ukOwningBusiness = g_scratchpad.owningBus.toString();
    var trdSettlementDate = g_scratchpad.settlementDate;


    if ((g_form.getValue('outcome') == "Settle Trade") && (ukOwningBusiness.indexOf('UK') > -1)) { //Check if Maker or Checker
        try {
            var trdDetails = new GlideAjax('x_hsb11_mss_c_proc.HSBCTradeTaskUtils');
            trdDetails.addParam('sysparm_name', 'settlementDateValidation');
            trdDetails.addParam('sysparm_tradeSetlDte', trdSettlementDate);
            trdDetails.addParam('sysparm_inputSetlDte', newValue);
            trdDetails.getXMLAnswer(handleResponse);
        } catch (error) {
		}

    }

    function handleResponse(response) {
        if (response.toString() != 'true') { //to limit if there are any warnings
            g_form.clearValue('settlement_date');
            g_form.showFieldMsg('settlement_date' ,response);
        }

    }

}
